\label{theoPartialGenerWatsonLemma}
Let $\M$ be a weight sequence, $\ga>0$ and $G_\ga$ be any sectorial region of opening $\pi\ga$. The following statements hold:
\begin{itemize}
\item[(i)] If $\ga>\o(\M)$, then $\widetilde{\mathcal{B}}:\widetilde{\mathcal{A}}_{\M}(G_{\gamma}) \longrightarrow \C[[z]] _\M$ is injective.
\item[(ii)] If $\ga<\o(\M)$, then $\widetilde{\mathcal{B}}:\widetilde{\mathcal{A}}_{\M}(G_{\gamma}) \longrightarrow \C[[z]] _\M$ is not injective.
\end{itemize}

\label{coroGenerWatsonLemmaSectorialRegions}
  Let $\M$ be a weight sequence, $\ga>0$ and $G_\ga$ be a sectorial region. The following statements are equivalent:
\begin{itemize}
\item[(i)] The Borel map $\widetilde{\mathcal{B}}:\widetilde{\mathcal{A}}_{\M}(G_{\gamma}) \longrightarrow \C[[z]] _\M$ is injective.
\item[(ii)] $\ga>\o(\M)$.
\end{itemize}

\label{comparisonmaintheorem}
Let $\omega$ be a normalized weight function satisfying \hyperlink{om3}{$(\omega_3)$}, \hyperlink{om4}{$(\omega_4)$} and $\gamma(\omega)>1$, and let $\Omega=\{W^x: x>0\}$ be the associated weight matrix. Then for all $0<\gamma<\gamma(\omega)-1$ and for all $x>0$ there exist $y>0$ and a continuous linear extension operator
\begin{equation}\label{comparisonthmequ0}
E^{\omega}_{\gamma,x}:\Lambda_{\omega,x}\longrightarrow\mathcal{A}_{\omega,y}(S_{\gamma}),
\end{equation}
i.e. $(\mathcal{B}E^{\omega}_{\gamma,x})(\lambda)=\lambda$ holds true for any sequence $\lambda\in\Lambda_{\omega,x}$.
In particular, the map
$\mathcal{B}:\mathcal{A}_{\{\omega\}}(S_{\gamma})\longrightarrow\Lambda_{\{\omega\}}$ is surjective.

\label{theoMandelbrojtUniformAsympt}
Let $\M$ be a weight sequence and $\ga>0$. The following statements are equivalent:
\begin{itemize}
\item[(i)] $\widetilde{\mathcal{B}}:\widetilde{\mathcal{A}}^u_{\M}(S_{\gamma}) \longrightarrow \C[[z]] _\M$ is injective.
\item[(ii)] $\sum^{\infty}_{p=0} (m_p)^{-1/\ga}=\infty$.
\item[(iii)] Either $\ga>\o(\M)$, or $\ga=\o(\M)$ and $\sum^{\infty}_{p=0} (m_p)^{-1/\o(\M)}=\infty$.
\end{itemize}

\label{th.BorelRittGevreySanz}
Let $\M$ be a weight sequence admitting a nonzero proximate order and $\ga>0$ be given. The following statements are equivalent:
\begin{itemize}
\item[(i)] $\gamma\le\omega(\M)=\ga(\M)$,
\item[(ii)] For every $\widehat{f}=\sum_{p\in\N_0} a_p z^p\in\C[[z]]_{\M}$ there exists a function $f\in\widetilde{\mathcal{A}}_{\bM}(S_{\gamma})$ such that $$f\sim_{\M}\widehat{f},$$
    i.e., $\widetilde{\mathcal{B}}(f)=\widehat{f}$. In other words, the Borel map $\widetilde{\mathcal{B}}:\widetilde{\mathcal{A}}_{\M}(S_{\gamma})\longrightarrow \C[[z]]_{\M}$ is surjective.
\end{itemize}
Hence, $\widetilde{S}_{\M}=(0,\ga(\M)]=(0,\o(\M)]$.

\label{propmequivm}
Let $\tau$ be a normalized weight function with $\gamma(\tau)>0$ which satisfies 
\hyperlink{om3}{$(\omega_3)$}, let $\mathcal{T}=\{T^x=(T^x_p)_{p\in\NN}:x>0\}$ be its associated weight matrix, and for $0<\gamma<\gamma(\tau)$ and $a>0$ let $G_a,e_a,m_a$ be the functions previously constructed. Then, there exist constants $C_1,C_2>0$, both depending on $a$, such that for every $p\in\NN$ one has
\begin{equation}
  \label{equaIneqMomentsMatrix}
  C_1(\frac{K_2}{2})^pT_p^{1/(2a)}\le m_a(p)\le C_2K_3^pT_{p}^{4/a},
\end{equation}
where $K_2$ and $K_3$ are the constants, not depending on $a$, appearing in Theorem~\ref{Theorem231tau}.

\label{Thilliezstrongcondition}
Let $M\in\RR_{>0}^{\NN}$ be given, the following are equivalent::

\begin{itemize}
\item[$(i)$] $\gamma(M)>1$,

\item[$(ii)$] there exists $n\in\hyperlink{LCset}{\mathcal{LC}}$, $n\hyperlink{simeq}{\simeq}m$, and $N$ has \hyperlink{gamma1}{$(\gamma_1)$},

\item[$(iii)$] there exists $N\in\hyperlink{LCset}{\mathcal{LC}}$, $N\hyperlink{simeq}{\simeq}M$, and $N$ has \hyperlink{gamma1}{$(\gamma_1)$}.
\end{itemize}
In particular, if $M\hyperlink{simeq}{\simeq}N$ with $N\in\hyperlink{LCset}{\mathcal{LC}}$, this yields the following equivalence (which should be compared with Lemma \ref{strongweightspace} in the weight function setting):
\begin{itemize}
\item[$(+)$] $\gamma(M)>1$,

\item[$(++)$] $M$ satisfies \hyperlink{gamma1}{$(\gamma_1)$}.
\end{itemize}

We revisit the definition of the growth index $\gamma(M)$ introduced in \cite[Section 1.3]{Thilliezdivision}. This is necessary if we pretend to explain the result about the mixed setting as a complement to the extension results by V.~Thilliez.

Let $\gamma\in\RR$ be given, then $M\in\RR_{>0}^{\NN}$ satisfies $(P_{\gamma})$ (see \cite[Definition 1.3.1]{Thilliezdivision} where only $\gamma>0$ was considered), if
\begin{equation}\label{Pgamma1}
\exists\;\nu=(\nu_p)_p\;\exists\;a\ge 1\;\forall\;p\in\NN:\;\;\;a^{-1}\mu_p\le\nu_p\le a\mu_p
\end{equation}
and such that
\begin{equation}\label{Pgamma2}
p\mapsto\frac{\nu_p}{p^{\gamma}}\;\;\text{is nondecreasing}.
\end{equation}
\eqref{Pgamma1} is precisely $M\hyperlink{simeq}{\simeq}N$ for $N=(N_p)_p$ given by $N_0:=1$, $N_p=\prod_{j=1}^p \nu_j$, $p\in\NN_{>0}$.

\label{th.SurjectivityNonUniformAsymp}
Let $\M$ be a weight sequence. 
\begin{itemize}
\item[(i)] Let $\alpha>0$, $\alpha\notin\N$, be such that $\widetilde{\mathcal{B}}:\widetilde{\mathcal{A}}_{\M}(S_{\alpha})\to \C[[z]]_\M$ is surjective. Then, $\ga(\M)>\lfloor \alpha \rfloor $.


\item[(ii)] If we have that $\widetilde{S}_{\M}=(0,\infty)$, then $\ga(\M)=\infty$.
\end{itemize}

\label{Theorem231tau}
Let $\tau$ be a weight function 
with $\gamma(\tau)>0$. Then for any $0<\gamma<\gamma(\tau)$ there exist constants $K_1,K_2,K_3>0$ depending only on $\tau$ and $\gamma$ such that for all $a>0$ there exists a function $G_a$ holomorphic in $S_{\gamma}$ and satisfying
\begin{equation}\label{Theorem231equtau}
\forall\;\xi\in S_{\gamma}:\;\;K_1^{-a}\exp(-2a\tau^{\iota}(K_2|\xi|)) \le|G_a(\xi)|\le
\exp(-\frac{a}{2}\tau^{\iota}(K_3|\xi|)).
\end{equation}
Moreover, if $\tau$ is normalized and satisfies  \hyperlink{om3}{$(\omega_3)$}, and $\mathcal{T}=\{T^x=(T^x_p)_{p\in\NN}:x>0\}$ is its associated weight matrix, then $G_a$ is a flat function in $\mathcal{A}_{\{\widehat{\mathcal{T}}\}}(S_{\gamma})$, where $\widehat{\mathcal{T}}$ is the standard log-convex weight matrix consisting of the sequences $\widehat{T}^x=(p!T^x_p)_{p\in\NN}$, $x>0$.

Finally, if we also assume that $\tau$ satisfies \hyperlink{om4}{$(\omega_4)$}, then there exist $x>0$ and $K_4>0$, both depending on $a$, such that
\begin{equation}\label{equaBoundsOptimalFlat}
\forall\;\xi\in S_{\gamma}: |G_a(\xi)|\ge K_4\,h_{T^{x}}(K_2|\xi|).
\end{equation}
